"""Original movement-disorders chapter: Parkinson disease management section."""
from qbank_authoring import question,ref,finalize
PD=ref('MDS Position: Diagnosis of Parkinson Disease','https://www.movementdisorders.org/MDS/News/Newsroom/Position-Papers/MDS-Position-Diagnosis-of-PD.htm')
AN=ref('AAN 2021 Early Parkinson Dopaminergic Therapy Guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC8672433/')
NI=ref('NICE NG71 Parkinson Disease Recommendations','https://www.nice.org.uk/guidance/ng71/chapter/Recommendations')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('What motor combination establishes parkinsonism as the prerequisite for applying MDS PD criteria?', 'Bradykinesia plus rest tremor or rigidity',[
 ('Rest tremor alone in every case','Tremor alone is insufficient.'),('Postural instability alone','Many disorders cause balance impairment without parkinsonism.'),('Any action tremor with normal repetitive movement','This does not establish the required bradykinetic syndrome.')],
 'Diagnose the syndrome before assigning the cause', '**Bradykinesia is essential in the MDS motor definition.**', ['Assess speed, amplitude and decrement with repetitive movement.','PD causality then depends on supportive features, red flags and exclusions.'], '**Do not equate every tremor with PD.**', ['Essential, dystonic, drug-related and physiological tremors are alternatives.','Longitudinal reassessment can reveal an atypical syndrome.'], [['Parkinsonism','Bradykinesia plus tremor/rigidity'],['PD','Cause assessment after syndrome'],['Tremor alone','Insufficient']], [PD])
q('During finger tapping, movement becomes progressively smaller and slower. Which cardinal feature is being demonstrated?', 'Bradykinesia with decrement',[
 ('Pure cerebellar dysmetria','This is an accuracy/coordination problem rather than the stated decrement pattern.'),('Spasticity','This is velocity-dependent resistance on passive examination.'),('Myoclonus','This consists of sudden brief jerks.')],
 'Slowness requires phenomenological characterization', '**The sequence effect supports bradykinesia rather than simply low effort or weakness.**', ['Compare sides and several tasks.','Pain, arthritis and weakness can confound performance.'], '**Combine the finding with the rest of the motor examination.**', ['Assess rigidity, rest tremor, gait and postural responses.','A single task does not settle the etiology.'], [['Decrement','Bradykinetic sequence effect'],['Weakness/pain','Possible confounders'],['Full examination','Determines syndrome']], [PD])
q('A patient has asymmetric bradykinesia, rigidity and a clear sustained levodopa response. What does this response contribute?', 'A supportive feature for PD, without being independently pathognomonic',[
 ('Definitive proof that no atypical disorder is possible','Some other parkinsonian disorders can respond.'),('An absolute exclusion of PD','A response supports rather than excludes it.'),('Proof that every nonmotor symptom must resolve','Dopamine responsiveness varies by symptom domain.')],
 'A treatment response modifies diagnostic confidence', '**A marked response is one supportive feature within the MDS framework.**', ['Look for red flags such as early severe autonomic or gaze abnormalities.','The disease course can change the diagnosis.'], '**Separate symptomatic efficacy from disease modification.**', ['Levodopa benefit does not prove slowed neurodegeneration.','Document which functional problems actually improve.'], [['Clear response','Supports PD'],['Red flags','Can counterbalance'],['Benefit','Symptomatic, not proof of cure']], [PD,AN], 'clinical_scenario')
q('What is the main role of dopamine transporter SPECT in a clinically uncertain tremor/parkinsonism case?', 'Support assessment of presynaptic dopaminergic deficit, while not reliably distinguishing PD from all degenerative atypical parkinsonisms',[
 ('Identify the exact alpha-synuclein or tau pathology in every patient','It is not a pathology-specific assay.'),('Replace the neurological examination','Clinical assessment remains central.'),('Prove that a normal scan means every symptom is functional','Other nondegenerative causes can produce symptoms.')],
 'Understand the biological question the scan answers', '**An abnormal scan can support nigrostriatal degeneration.**', ['PD, MSA and PSP can all show a deficit.','Selected drug-induced or essential tremor cases can have preserved uptake.'], '**Use it only for a useful diagnostic uncertainty.**', ['Medication effects and technical interpretation matter.','A scan result should not override a clearly discordant clinical phenotype without review.'], [['Deficit','Presynaptic dopamine loss'],['Etiological specificity','Limited among degenerative syndromes'],['Clinical context','Still required']], [PD,NI])
q('A newly diagnosed PD patient has motor symptoms affecting daily life. Which drug offers the greatest established symptomatic motor benefit and is commonly preferred initially?', 'Levodopa with a peripheral decarboxylase inhibitor',[
 ('A dopamine agonist is always superior regardless of age or cognition','Agonists have important behavioral, sleep and hallucination risks.'),('An anticholinergic in every older adult','Cognitive and other adverse effects limit use.'),('No treatment until the patient is bedbound','Meaningful symptomatic benefit should not be withheld that long.')],
 'Choose initial therapy for functional need and individual risk', '**AAN favors levodopa as the initial dopaminergic therapy for many patients seeking motor benefit.**', ['NICE recommends offering it when symptoms affect quality of life.','Use the lowest effective dose and review response.'], '**Explain future complications without denying current function.**', ['Dyskinesia risk is relevant but not a reason for arbitrary prolonged avoidance.','Age, occupation, cognition and patient preferences guide the discussion.'], [['Levodopa','Strongest motor benefit'],['Agonist','Selected alternative with specific risks'],['Decision','Function and patient context']], [AN,NI], 'clinical_scenario')
q('Why is carbidopa combined with levodopa?', 'It reduces peripheral decarboxylation, increasing delivery to the brain and reducing peripheral adverse effects',[
 ('It directly substitutes for dopamine receptors in the striatum','That describes a different pharmacological approach.'),('It blocks all levodopa entry into the brain','The intended effect is improved availability.'),('It proves the disease has been cured','This is symptomatic therapy.')],
 'Protect the precursor before it reaches its target', '**Peripheral enzyme inhibition improves the usable fraction of levodopa.**', ['It can reduce nausea and other peripheral dopamine effects.','It does not prevent all central adverse effects such as hallucinations or dyskinesia.'], '**Assess both benefit and tolerability.**', ['Dose timing and formulation affect response.','Do not treat a peripheral inhibitor as an independent definitive PD treatment.'], [['Levodopa','Dopamine precursor'],['Carbidopa','Peripheral decarboxylase inhibition'],['Remaining risks','Central dopaminergic effects']], [AN,NI])
q('A levodopa-treated patient has predictable symptom return before each dose. What is this pattern?', 'Wearing-off',[
 ('Peak-dose dyskinesia','That is excess involuntary movement near maximum drug effect.'),('A fixed complete loss of all drug efficacy','The predictable dose cycle implies ongoing response.'),('A mandatory diagnosis of functional symptoms','The pharmacological timing is a recognized motor complication.')],
 'Relate motor state to the medication cycle', '**Wearing-off reflects shortened benefit from each dose.**', ['A diary can clarify timing and nonmotor OFF symptoms.','Absorption and meal interactions can worsen variability.'], '**Optimize delivery before adding treatment blindly.**', ['Dose fractionation or a suitable MAO-B/COMT inhibitor or agonist can help selected patients.','Balance extra ON time against dyskinesia, pressure and neuropsychiatric effects.'], [['End-of-dose OFF','Wearing-off'],['Peak effect with choreiform movement','Peak-dose dyskinesia'],['Diary','Clarifies cycle']], [NI], 'clinical_scenario')
q('Which drug class can extend levodopa effect by inhibiting its catechol-O-methyltransferase metabolism?', 'COMT inhibitors such as entacapone or opicapone',[
 ('Peripheral dopamine antagonists as the identical motor strategy','These do not provide the same levodopa-metabolism effect.'),('Acetylcholinesterase inhibitors','These target a different symptom domain.'),('VMAT2 inhibitors','These reduce monoamine vesicular storage and can worsen parkinsonism.')],
 'An adjunct can change exposure to an existing effective drug', '**COMT inhibition is used with levodopa for appropriate motor fluctuations.**', ['It is not useful as a stand-alone dopamine replacement strategy.','Greater dopaminergic exposure can increase dyskinesia.'], '**Review levodopa dose and adverse effects after addition.**', ['The best adjunct depends on the whole symptom profile.','Agent-specific warnings and interactions still matter.'], [['COMT inhibition','Extends levodopa availability'],['Use','Adjunct for fluctuations'],['Tradeoff','More dyskinesia possible']], [NI])
q('What is the mechanism of rasagiline or selegiline in PD?', 'MAO-B inhibition that reduces dopamine breakdown',[
 ('Irreversible destruction of nigrostriatal terminals','This is not the therapeutic mechanism.'),('Direct removal of alpha-synuclein inclusions as a proven cure','No such curative claim is established.'),('Peripheral iron chelation','This is unrelated.')],
 'Understand symptom amplification without claiming neuroprotection', '**MAO-B inhibitors can provide modest motor benefit or serve as fluctuation adjuncts.**', ['Interactions, including serotonergic and other drugs, require review.','They do not have proven curative disease-modifying action.'], '**Select according to effect size and risk.**', ['A patient with substantial disability may need levodopa.','Monitor sleep, pressure and other adverse effects.'], [['Target','MAO-B'],['Effect','Less dopamine breakdown'],['Limit','Not proven cure/neuroprotection']], [AN,NI])
q('A patient develops new compulsive gambling and hypersexual behavior after pramipexole escalation. What adverse effect is most likely?', 'Dopamine agonist-associated impulse-control disorder',[
 ('An inevitable symptom of every untreated PD patient','The medication association is important and modifiable.'),('Proof that levodopa can never be used','This does not preclude an alternative dopaminergic plan.'),('A benign behavior that should not be discussed','Financial and interpersonal harm can be severe.')],
 'Motor benefit can coexist with hidden behavioral toxicity', '**Agonists carry a higher impulse-control risk than levodopa.**', ['Ask directly and include trusted caregivers when appropriate.','Shopping, eating and repetitive behaviors can also occur.'], '**Reduce/switch through a supervised plan.**', ['Abrupt agonist withdrawal can cause a difficult withdrawal syndrome.','Preserve motor control and provide behavioral support.'], [['Drug clue','Agonist dose change'],['Risk','Gambling/sexual/eating/shopping behaviors'],['Action','Supervised medication review']], [AN,NI], 'clinical_scenario')
q('Why are dopamine agonists often less suitable in an older PD patient with hallucinations, cognitive impairment or excessive sleepiness?', 'They can worsen hallucinations, somnolence and behavioral problems',[
 ('They have no central nervous system effects','Their central effects are the basis of both benefit and toxicity.'),('They always reverse dementia','This is not established.'),('Age completely removes impulse-control risk','Risk remains relevant.')],
 'Select treatment for the patient’s vulnerable domains', '**Agonist adverse effects can outweigh a theoretical dyskinesia advantage in this setting.**', ['Sudden sleep episodes affect driving and safety.','Orthostatic effects can add falls risk.'], '**Use the simplest effective regimen where possible.**', ['Levodopa may offer a better balance.','Review sedatives, cognition and sleep disorders as well.'], [['Vulnerable cognition','Hallucination risk'],['Daytime sleepiness','Safety concern'],['Alternative','Individualized levodopa-centered approach']], [AN,NI])
q('A patient has troublesome levodopa-induced dyskinesia despite appropriate adjustment of the regimen. Which drug can be considered?', 'Amantadine',[
 ('Haloperidol as routine chronic antidyskinetic treatment','Dopamine blockade can worsen parkinsonism.'),('Increasing every levodopa dose without review','This can increase dyskinesia.'),('Stopping all dopaminergic treatment abruptly','This can cause severe withdrawal-related deterioration.')],
 'Treat the motor complication while preserving useful ON function', '**Amantadine can reduce dyskinesia in selected patients.**', ['Renal function influences exposure.','Hallucinations, confusion and other adverse effects can limit use.'], '**Assess the pattern before choosing a drug.**', ['Peak-dose, diphasic and OFF dystonic problems can require different adjustments.','Advanced therapy may be relevant when fluctuations remain severe.'], [['Dyskinesia','Identify dose-cycle pattern'],['Amantadine','Selected antidyskinetic option'],['Safety','Renal/cognitive review']], [NI], 'clinical_scenario')
q('Why can an abrupt interruption of dopaminergic medication during hospital admission be dangerous?', 'It can precipitate severe akinesia and a hyperpyrexia/rigidity syndrome',[
 ('PD medication timing is irrelevant once admitted','Time-critical dosing remains important.'),('All levodopa can safely be withheld for a week without a plan','This can cause major deterioration.'),('A nil-by-mouth order eliminates the need for any alternative strategy','A safe alternative route/regimen may be necessary.')],
 'Hospital logistics must not create a withdrawal emergency', '**Maintain the patient’s established schedule as accurately as possible.**', ['Vomiting, poor absorption or NPO status requires specialist planning.','Fever, rigidity and autonomic change demand urgent assessment.'], '**Coordinate pharmacy, nursing and neurology care.**', ['Do not substitute a formulation without checking equivalence.','Investigate infection and other triggers alongside medication interruption.'], [['Missed doses','Time-sensitive risk'],['NPO','Alternative plan needed'],['Severe rigidity/fever','Emergency assessment']], [NI])
q('Which patient is a more appropriate DBS candidate?', 'A levodopa-responsive patient with disabling motor fluctuations despite optimized therapy and preserved cognition without uncontrolled psychiatric disease',[
 ('A patient whose main problem is advanced dementia','DBS can worsen function and is not a dementia treatment.'),('A patient with a wholly levodopa-unresponsive atypical axial syndrome','Benefit is less likely for the principal resistant symptoms.'),('Every patient at first diagnosis regardless of medication response','Selection requires substantial assessment.')],
 'DBS treats selected motor circuitry rather than every aspect of PD', '**Levodopa-responsive motor complications often predict a useful target.**', ['Medication-resistant tremor can also be a selected indication.','Neuropsychological and psychiatric assessment is essential.'], '**Explain what surgery may not improve.**', ['Cognition, autonomic disease and resistant balance/speech problems may persist.','Target selection and expectations are individualized.'], [['Good target','Responsive fluctuations/tremor'],['Major caution','Dementia/uncontrolled psychiatric illness'],['Expectation','Not a global cure']], [NI], 'clinical_scenario')
q('Does DBS reliably correct all levodopa-resistant postural instability, speech and cognitive problems?', 'No; these domains often respond poorly and can worsen in some settings',[
 ('Yes, it reverses every nonmotor manifestation','This overstates the treatment.'),('Yes, target selection and cognition are irrelevant','They are important.'),('No motor symptom ever benefits','Appropriately selected motor symptoms can improve markedly.')],
 'A circuit intervention has a symptom-specific effect profile', '**The expected benefit should be matched to the patient’s disabling problem.**', ['A levodopa challenge and careful examination help predict response.','Programming can involve motor and speech tradeoffs.'], '**Do not promise a disease-modifying cure.**', ['Disease progression continues.','Rehabilitation and medication review remain necessary.'], [['Responsive motor symptom','Potential benefit'],['Resistant axial/cognitive symptom','Limited expectation'],['Long term','Progression and ongoing care']], [NI])
q('A PD patient has distressing hallucinations. What is the appropriate initial principle?', 'Assess delirium, infection, vision, sleep and medication contributors before selecting a PD-compatible treatment',[
 ('Use haloperidol routinely without review','Dopamine blockade can cause severe motor worsening.'),('Assume every hallucination proves a primary psychiatric disorder','PD, medicines and delirium can contribute.'),('Stop all levodopa abruptly','This risks severe motor deterioration.')],
 'Psychosis management begins with reversible contributors', '**A new acute change warrants a delirium work-up.**', ['Review anticholinergics, amantadine, agonists and other contributing medicines.','Tolerated non-distressing hallucinations may not require an antipsychotic.'], '**If treatment is needed, use a specialist PD-compatible strategy.**', ['Clozapine has evidence but requires blood monitoring; other choices depend on context and local availability.','Balance symptom control against sedation and motor effects.'], [['Acute change','Assess delirium'],['Drug contributors','Review systematically'],['Antipsychotic choice','PD-compatible specialist plan']], [NI], 'clinical_scenario')
q('Which treatment has a role in Parkinson disease dementia?', 'A cholinesterase inhibitor such as rivastigmine',[
 ('A dopamine agonist as proven universal dementia reversal','It can worsen hallucinations and is not that treatment.'),('Chronic high-dose anticholinergic therapy','This can worsen cognition.'),('Levodopa withdrawal as the only cognitive treatment','This can sacrifice mobility without treating the cognitive syndrome.')],
 'Motor and cognitive targets require different strategies', '**Cholinergic treatment can provide symptomatic cognitive benefit in selected PD dementia.**', ['Assess bradycardia, gastrointestinal effects and other contraindications.','The expected improvement is modest and not curative.'], '**Address reversible cognitive burdens.**', ['Review sleep, mood, hearing, vision, infection and medicines.','Provide caregiver and functional support.'], [['Rivastigmine','Symptomatic cognitive option'],['Anticholinergics','Potential cognitive harm'],['Support','Patient and caregiver needs']], [NI])
q('A PD patient becomes dizzy on standing. What is the appropriate first assessment?', 'Measure supine and standing pressure and review medicines, hydration and neurogenic/autonomic features',[
 ('Assume every episode is an OFF tremor','Orthostatic symptoms need direct assessment.'),('Increase every blood-pressure-lowering drug','This can worsen symptoms.'),('A single seated normal BP excludes the problem','The postural change is what matters.')],
 'Autonomic symptoms can be compounded by treatment and other illness', '**Dopaminergic drugs, antihypertensives, dehydration and neurogenic dysfunction can contribute.**', ['Assess falls and syncope risk.','Supine hypertension can complicate treatment.'], '**Start with a cause- and safety-based plan.**', ['Nonpharmacological measures and selected pressor drugs may help.','Monitor the tradeoff between upright symptoms and supine pressure.'], [['Measurement','Supine/standing'],['Contributors','Drugs, volume and autonomic disease'],['Treatment','Individualized with supine review']], [NI], 'clinical_scenario')
q('REM sleep behavior disorder, hyposmia and constipation can precede motor PD. What is the correct interpretation?', 'They are supportive prodromal clues but are not individually sufficient to diagnose motor PD',[
 ('Every patient with constipation has PD','These symptoms are common and nonspecific.'),('They exclude a synucleinopathy','They can support that context.'),('A prodromal clue proves the exact future course','Progression risk is variable.')],
 'Nonmotor features change probability without establishing certainty', '**RBD is particularly relevant to a synucleinopathy risk assessment.**', ['Other disorders and medicines can explain similar symptoms.','Clinical motor criteria are still required for the usual motor PD diagnosis.'], '**Offer appropriate symptom and safety care.**', ['RBD can create injury risk and may warrant sleep assessment.','Do not communicate a deterministic diagnosis from one clue.'], [['Prodromal clue','Probability information'],['Motor diagnosis','Requires motor syndrome'],['Counseling','Avoid certainty beyond evidence']], [PD,NI])
q('A levodopa-treated patient reports worse ON response after a large protein-rich meal. What mechanism may contribute?', 'Competition involving amino-acid transport and delayed/variable gastrointestinal delivery',[
 ('Protein instantly destroys all substantia nigra neurons','This is not the mechanism.'),('The drug can never interact with food','Food can alter response.'),('All dietary protein should be eliminated permanently','This risks malnutrition and sarcopenia.')],
 'A nutrient interaction should be managed without creating deficiency', '**Meal timing and protein distribution can affect levodopa benefit.**', ['Gastroparesis can add variability.','Dietitian input can help preserve adequate total nutrition.'], '**Use a targeted timing strategy.**', ['Do not impose severe indiscriminate protein restriction.','Review weight, swallowing and nutritional status.'], [['Protein meal','Can alter response'],['Diet plan','Timing/distribution'],['Total nutrition','Preserve adequacy']], [NI], 'clinical_scenario')
q('Which nonpharmacological interventions are central to PD care?', 'Regular appropriate exercise with physiotherapy, occupational and speech/swallow support according to deficits',[
 ('Bed rest as a universal long-term strategy','Inactivity worsens deconditioning.'),('Medication alone eliminates all rehabilitation needs','Speech, swallowing, gait and function often need targeted support.'),('Exercise is a proven complete replacement for indicated motor medicines','It complements rather than universally replaces treatment.')],
 'Treat function across several domains', '**A multidisciplinary approach improves practical management.**', ['Falls, home safety, communication and swallowing need specific assessment.','Exercise should fit fitness, balance and comorbidity.'], '**Reassess as the disease changes.**', ['Caregiver support and advance planning are relevant.','The plan should follow the patient’s priorities.'], [['Motor medicine','Symptom control'],['Rehabilitation','Function and safety'],['Multidisciplinary care','Changing needs']], [NI])
q('A patient remains severely fluctuating despite optimized oral levodopa. What is an appropriate next principle?', 'Assess advanced delivery or device-based options through a specialist service rather than endlessly adding unsupervised doses',[
 ('Every patient must receive DBS regardless of cognition','Selection matters.'),('No treatment beyond immediate-release tablets exists','Infusion and other advanced strategies are available.'),('A continuous-delivery option is guaranteed to reverse dementia','These mainly target selected motor complications.')],
 'Delivery failure can be a treatable part of advanced motor disease', '**Options include selected apomorphine, intestinal or subcutaneous levodopa strategies and DBS according to availability and suitability.**', ['Support needs and device complications matter.','Cognition, psychiatric state and remaining levodopa response guide selection.'], '**Match the technology to the patient rather than the other way around.**', ['Define the target symptom and expected benefit.','Continue nutrition, rehabilitation and nonmotor care.'], [['Advanced option','Specialist selection'],['Target','Motor fluctuation/delivery problem'],['Whole-patient care','Still essential']], [NI], 'clinical_scenario')
